-- RayValue: United Kingdom (GB) solar + battery calculator data. First non-US calculator at /uk/solar-calculator.
-- APPLY ORDER: after 0034. Additive only. NOT applied by the commit that adds this file: the owner applies it.
--
-- What this adds (every number has a source_url + verified_on, or a rationale if it is a product choice):
--   * region 'GB' (national figures; published=false so no place page uses it)
--   * 14 utilities = the 14 Ofgem price cap regions (electricity, Direct Debit, Oct-Dec 2026), rate_type 'flat'
--   * 8 named SEG / export offers as export_policies (+ dated export_policy_rates)
--   * vat_rates: date-effective VAT on installed solar and batteries (0% to 31 Mar 2027, 5% from 1 Apr 2027)
--   * cost_ranges for installed solar (DESNZ/MCS 2025/26) and a retrofit battery (DESNZ/MCS 2025/26)
--   * model_assumptions for GB (product choices with rationale)
--   * calculator_locations: one representative place per price cap region, for the PVGIS yield lookup
-- There is no incentive row: GB has no universal solar grant (the Warm Homes Loan is a loan, not a payment).
-- Retrieved / verified on 2026-11-22.

-- ------------------------------------------------------------------ schema changes

alter table public.utilities drop constraint utilities_rate_type_check;
alter table public.utilities add constraint utilities_rate_type_check check (rate_type in ('tiered', 'tou_summary', 'flat'));
comment on column public.utilities.rate_type is 'tiered (FL), tou_summary (CA) or flat (one published unit rate + standing charge, e.g. the Ofgem price cap; avg_rate_* holds the unit rate).';

create table public.vat_rates (
  id            text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  country       text not null references public.markets (code) on update cascade,
  applies_to    text not null check (applies_to in ('solar', 'battery')),
  rate          numeric not null check (rate >= 0 and rate < 1),
  valid_from    date,
  valid_to      date,
  note          text,
  source_url    text not null check (source_url ~ '^https?://'),
  publisher     text,
  verified_on   date not null,
  verification  text not null check (verification in ('agent_sourced', 'human_verified')),
  updated_at    timestamptz not null default now(),
  constraint vat_rates_dates check (valid_to is null or valid_from is null or valid_to >= valid_from)
);
comment on table public.vat_rates is 'Date-effective VAT/GST on installed solar and batteries per country. The calculator picks the row whose window contains the install date; no row = missing data, never a default. markets.vat_rate stays null where the rate changes over time.';
comment on column public.vat_rates.rate is 'Fraction: 0 = zero-rated, 0.05 = 5%.';

create table public.calculator_locations (
  id               text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  country          text not null references public.markets (code) on update cascade,
  region_code      text not null,
  utility_id       text not null references public.utilities (id) on update cascade on delete cascade,
  name             text not null check (name <> ''),
  lat              numeric not null check (lat between -90 and 90),
  lon              numeric not null check (lon between -180 and 180),
  coord_source_url text not null check (coord_source_url ~ '^https?://'),
  verified_on      date not null,
  verification     text not null check (verification in ('agent_sourced', 'human_verified')),
  note             text,
  updated_at       timestamptz not null default now(),
  foreign key (country, region_code) references public.regions (country, code) on update cascade
);
comment on table public.calculator_locations is 'The point whose solar yield (PVGIS) stands for a calculator region (here: an Ofgem price cap region). One row per utility. A product choice about WHERE to look up yield; the coordinates themselves are sourced.';

create trigger set_updated_at before update on public.vat_rates for each row execute function public.set_updated_at();
create trigger set_updated_at before update on public.calculator_locations for each row execute function public.set_updated_at();

do $$
declare t text;
begin
  foreach t in array array['vat_rates', 'calculator_locations']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
    execute format('grant select on table public.%I to anon', t);
    execute format('grant select, insert, update, delete on table public.%I to service_role', t);
    execute format('create policy "Public reference data is readable" on public.%I for select to anon using (true)', t);
  end loop;
end;
$$;

-- ------------------------------------------------------------------ market + region

update public.markets set
  prices_include_tax = true,
  display_round = 50,
  display_round_rationale = 'Assumption: round money to the nearest GBP 50 so that small homes (savings of a few hundred pounds a year) are not rounded to the nearest GBP 100.',
  vat_note = 'VAT on installed solar and batteries changes over time (0% to 31 Mar 2027, 5% from 1 Apr 2027): see public.vat_rates. markets.vat_rate stays null on purpose.'
where code = 'GB';

insert into public.regions (country, code, name, slug, published) values
  ('GB', 'GB', 'Great Britain (national figures)', 'great-britain', false)
on conflict (country, code) do nothing;


