  ('gb-british-gas-export-premium', null, null, 1, null, 0.12, '12 pence per kWh exported, as published by British Gas on 2026-11-22.', 'https://britishgas.co.uk/energy/smart-export-guarantee.html', '2026-11-22', 'agent_sourced');

-- ------------------------------------------------------------------ date-effective VAT on installs
-- HMRC VAT Notice 708/6: installation of energy-saving materials (incl. solar panels) is zero-rated 1 May 2023 to 31 Mar 2027 and reverts to 5% from 1 Apr 2027.
-- Batteries: zero-rated from 1 Feb 2024 (HMRC VENSAV3061), same end date. Budget 2026 OOTLAR repeats the 1 Apr 2027 reversion to 5%.
insert into public.vat_rates (id, country, applies_to, rate, valid_from, valid_to, note, source_url, publisher, verified_on, verification) values
  ('gb-solar-zero-rate', 'GB', 'solar', 0, '2023-05-01', '2027-03-31', 'Temporary zero rate for installing solar panels in residential accommodation.', 'https://www.gov.uk/guidance/vat-on-energy-saving-materials-and-heating-equipment-notice-7086', 'HMRC VAT Notice 708/6', '2026-11-22', 'agent_sourced'),
  ('gb-solar-reduced-rate', 'GB', 'solar', 0.05, '2027-04-01', null, 'Reverts to the reduced rate of 5% from 1 April 2027 (scheduled; confirmed again in the Budget 2026 overview of tax legislation and rates). A change in law would need a new row.', 'https://www.gov.uk/guidance/vat-on-energy-saving-materials-and-heating-equipment-notice-7086', 'HMRC VAT Notice 708/6', '2026-11-22', 'agent_sourced'),
  ('gb-battery-zero-rate', 'GB', 'battery', 0, '2024-02-01', '2027-03-31', 'Temporary zero rate for retrofitting a battery that stores electricity from a microgeneration system, and for standalone batteries storing grid electricity, in residential accommodation.', 'https://www.gov.uk/hmrc-internal-manuals/vat-energy-saving-materials-and-grant-funded-heating-supplies/vensav3061', 'HMRC VENSAV3061', '2026-11-22', 'agent_sourced'),
  ('gb-battery-reduced-rate', 'GB', 'battery', 0.05, '2027-04-01', null, 'Reduced rate of 5% after the temporary zero rate ends (HMRC Notice 708/6: energy-saving materials revert to 5% from 1 April 2027).', 'https://www.gov.uk/guidance/vat-on-energy-saving-materials-and-heating-equipment-notice-7086', 'HMRC VAT Notice 708/6', '2026-11-22', 'agent_sourced');

-- ------------------------------------------------------------------ installed costs
-- Solar: DESNZ 'Average costs of small-scale solar PV (TIC)', published 28 May 2026, financial year 2025/26, Great Britain, MCS installs, battery excluded.
-- Battery: DESNZ 'MCS certified domestic battery installation statistics', published 28 May 2026, financial year 2025/26, retrofit in existing homes.
-- includes_tax = false: both datasets include VAT 'where applicable', and installs were zero-rated throughout 2025/26, so the figures are ex-VAT in practice;
-- the engine adds the VAT that applies on the install date (public.vat_rates).
insert into public.cost_ranges (country, region_code, item, low, likely, high, unit, note, source_url, verified_on, verification, includes_tax) values
  ('GB', 'GB', 'installed_cost_per_watt', 1.54589, 1.77243, 2.10865, 'GBP per watt DC (DESNZ GBP per kW / 1,000)', 'Range built only from published DESNZ/MCS 2025/26 GB figures (TIC basis, per kW of total installed capacity, battery excluded, Northern Ireland excluded): low = median of all 4-10 kW installs, GBP 1,545.89/kW; likely = mean of all domestic installs, GBP 1,772.43/kW (sheet Domestic costs); high = mean of domestic retrofit 0-4 kW installs, GBP 2,108.65/kW (sheet New build costs). Divided by 1,000 to give GBP per watt. Small systems cost more per kW than large ones, so the high end is the small-system retrofit mean. Figures include VAT where applicable; domestic solar was zero-rated throughout 2025/26, so they are treated as ex-VAT and VAT on the install date is added separately. Not a quote: installer prices vary. Next DESNZ release: 27 May 2027.', 'https://assets.publishing.service.gov.uk/media/6a1709e4050971fbebf3bb3b/Solar_Costs_2025-26__TIC_.xlsx', '2026-11-22', 'agent_sourced', false),
  ('GB', 'GB', 'battery_installed_cost', null, 8722, null, 'GBP per battery system (about 9.8 kWh)', 'One battery = the 6-10.99 kWh retrofit band, 2025/26: median GBP 890/kWh (n = 14,457, DESNZ rounds to the nearest GBP 10) x 9.8 kWh average capacity of that band (141,650 kWh total / 14,457 installs) = GBP 8,722. Existing homes only; includes equipment, installation and VAT where applicable (batteries were zero-rated throughout 2025/26, so treated as ex-VAT; VAT on the install date is added separately). DESNZ gives no interval, so low and high are null and the engine adds +/- the missing-range spread and labels them estimated. Other bands (median per kWh, 2025/26): 1-5.99 kWh GBP 1,300; 11-29.99 kWh GBP 630.', 'https://assets.publishing.service.gov.uk/media/6a15faac5e28c5cac81cf144/MCS_domestic_retrofit_battery_installations_2025_2026.xlsx', '2026-11-22', 'agent_sourced', false);

-- ------------------------------------------------------------------ assumptions (product choices, not facts: each has a rationale)
insert into public.model_assumptions (key, country, region_code, value, unit, rationale) values
  ('pvwatts_system_loss_pct', 'GB', null, '{"none": 14, "some": 20, "heavy": 30}'::jsonb, 'percent', 'PVGIS system losses (the key keeps its legacy name). 14% is the PVGIS default system loss and is what every GB yield figure on the site uses; 20% (some shade) and 30% (heavy shade) are product choices that step the loss up for partial and heavy shade. Not sourced.'),
  ('target_offset', 'GB', null, '{"low": 0.8, "high": 1.0}'::jsonb, 'fraction of annual usage', 'Product choice: size the system to cover 80% to 100% of estimated annual usage, which gives the low and high ends of the suggested size range. Not sourced.'),
  ('system_size_cap_kw', 'GB', null, '{"value": 10}'::jsonb, 'kW DC', 'Product choice: the DESNZ/MCS cost data used for pricing stops at the 4-10 kW band for homes, so the suggested size is capped at 10 kW rather than priced outside the data. Not sourced.'),
  ('min_system_size_kw', 'GB', null, '{"value": 1.5}'::jsonb, 'kW DC', 'Product choice: below this a payback figure is not meaningful for a rooftop installation, so the calculator warns instead. Not sourced.'),
  ('max_monthly_bill', 'GB', null, '{"value": 1000}'::jsonb, 'GBP per month', 'Input sanity limit for the monthly bill field, so a typing slip (an extra zero) is caught. Not sourced.'),
  ('panel_degradation_per_year', 'GB', null, '{"value": 0.005}'::jsonb, 'fraction per year', 'Product choice: 0.5% less output each year, a conventional planning figure for crystalline silicon panels. Not sourced; replace with a datasheet or published study value if the owner prefers.'),
  ('analysis_years', 'GB', null, '{"value": 25}'::jsonb, 'years', 'Product choice: a 25-year projection with no discounting, the same horizon as the US calculator. Inverter and battery replacement are not modelled.'),
  ('missing_range_spread', 'GB', null, '{"value": 0.15}'::jsonb, 'fraction', 'Product choice: where a source gives a likely value but no bounds (the battery cost and each export rate), low and high are likely -/+ 15% and the result says they are estimated. Placeholder until bounds are sourced.'),
  ('annual_rate_escalation', 'GB', null, '{"low": 0, "likely": 0.02, "high": 0.04}'::jsonb, 'fraction per year', 'Product choice: electricity prices flat (low), rising 2% a year (likely) or 4% a year (high). Not a forecast; the Ofgem cap changes every quarter and can fall as well as rise.'),
  ('self_consumption_share', 'GB', null, '{"solar_only": {"low": 0.3, "likely": 0.4, "high": 0.55}, "solar_plus_1_battery": {"low": 0.55, "likely": 0.7, "high": 0.85}, "solar_plus_2_batteries": {"low": 0.7, "likely": 0.85, "high": 0.95}}'::jsonb, 'fraction of solar output used at home', 'NO PRIMARY SOURCE FOUND (listed in docs/TODO-VERIFY.md). A deliberately wide product-choice range: how much of the solar output is used in the home rather than exported depends on when the household is at home. Secondary guides (for example Uswitch, about 30% without a battery and 70% or more with one; Utilita citing the MCS procedure at 54%) were read as context only. Replace with a primary figure when one is found.'),
  ('orientation_yield_factor', 'GB', null, '{"east_west": {"low": 0.773, "likely": 0.789, "high": 0.81}, "north": {"low": 0.523, "likely": 0.537, "high": 0.558}}'::jsonb, 'fraction of south-facing yield', 'Derived from 12 PVGIS 5.3 runs (1 kWp, 35 degree tilt, 14% losses, PVGIS-SARAH3) for London, Manchester and Edinburgh, in the research pack: yield facing east, west or north divided by yield facing south. East/west ratios: London 0.802 / 0.773, Manchester 0.810 / 0.792, Edinburgh 0.780 / 0.776 (low = smallest, high = largest, likely = mean of the six). North: 0.531, 0.558, 0.523 (likely = mean). South-facing yield itself comes live from PVGIS at the optimal tilt. Only the likely factor feeds the calculation; low and high are shown as the spread. Source runs: https://re.jrc.ec.europa.eu/api/v5_3/PVcalc?lat=51.5072&lon=-0.1275&peakpower=1&loss=14&angle=35&aspect=-90&outputformat=json (aspect=0 south, -90 east, 90 west, 180 north; same pattern for each city).');

